    h, w = len(grid), len(grid[0])

    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r - 1][c] == 2 and grid[r + 1][c] == 2 and
                grid[r][c - 1] == 2 and grid[r][c + 1] == 2):
                centers.append((r, c))

    # Connect only consecutive diamonds along a shared row or column.
    for r, c in centers:
        for dr, dc in ((0, 1), (1, 0)):
            aligned = sorted(
                (rr, cc) for rr, cc in centers
                if (dr == 0 and rr == r and cc > c) or
                   (dc == 0 and cc == c and rr > r)
            )
            if not aligned:
                continue
            rr, cc = aligned[0]
            if dr == 0:
                for x in range(c + 2, cc - 1):
                    if out[r][x] == 0:
                        out[r][x] = 1
            else:
                for x in range(r + 2, rr - 1):
                    if out[x][c] == 0:
                        out[x][c] = 1

    return out
